import{_ as a,c as t,o as i,ag as o}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Gephi","description":"","frontmatter":{"title":"Gephi"},"headers":[],"relativePath":"general/gephi.md","filePath":"general/gephi.md","lastUpdated":null}'),s={name:"general/gephi.md"};function r(n,e,l,h,p,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="gephi" tabindex="-1">Gephi <a class="header-anchor" href="#gephi" aria-label="Permalink to &quot;Gephi&quot;">​</a></h1><h2 id="about-gephi" tabindex="-1">About Gephi <a class="header-anchor" href="#about-gephi" aria-label="Permalink to &quot;About Gephi&quot;">​</a></h2><p>Gephi is an open-source network visualization software that is a powerful tool for researchers, data scientists, marketers, and social scientists. It is designed to handle large datasets and create various network visualizations to uncover complex systems’ underlying patterns, structures, and dynamics. Gephi is widely used for social network analysis, link analysis, and biological network analysis, among other applications.</p><h3 id="what-can-gephi-be-used-for" tabindex="-1">What Can Gephi Be Used For? <a class="header-anchor" href="#what-can-gephi-be-used-for" aria-label="Permalink to &quot;What Can Gephi Be Used For?&quot;">​</a></h3><ul><li><p><strong>Social Network Analysis</strong>: Understanding social structures through visualizing networks of individuals or groups and their interactions.</p></li><li><p><strong>Link Analysis</strong>: Identifying relationships and structures in data, including detecting communities, influencers, and the flow of information.</p></li><li><p><strong>Biological Network Analysis</strong>: Mapping the interactions between biological entities such as genes, proteins, or species to uncover biological processes and pathways.</p></li><li><p><strong>Marketing and Behavior Change</strong>: Analyzing customer networks to identify key influencers and target marketing efforts more effectively. Gephi can reveal how information spreads through networks, helping to craft strategies for behavior change campaigns or viral marketing.</p></li></ul><h3 id="anecdotes" tabindex="-1">Anecdotes <a class="header-anchor" href="#anecdotes" aria-label="Permalink to &quot;Anecdotes&quot;">​</a></h3><ul><li><p>A digital marketing firm used Gephi to analyze the Twitter network of a major brand’s followers, identifying key influencers who were not previously recognized through traditional metrics. Engaging with these influencers significantly increased campaign reach and engagement.</p></li><li><p>In a behavior change campaign aimed at promoting healthy habits, public health researchers used Gephi to map the social networks of community members. The analysis revealed unexpected pathways for information dissemination, allowing for a more targeted intervention strategy.</p></li></ul><h3 id="list-of-terms" tabindex="-1">List of Terms <a class="header-anchor" href="#list-of-terms" aria-label="Permalink to &quot;List of Terms&quot;">​</a></h3><ul><li><p><strong>Nodes</strong>: The entities in the network (e.g., individuals, organizations, genes) represented as points.</p></li><li><p><strong>Edges</strong>: The connections between nodes, representing relationships or interactions.</p></li><li><p><strong>Centrality Measures</strong>: Metrics that identify the most important nodes within a network (e.g., degree centrality, betweenness centrality).</p></li><li><p><strong>Community Detection</strong>: The process of identifying clusters or groups of nodes that are more densely connected than the rest of the network.</p></li><li><p><strong>Modularity</strong>: A measure that quantifies the strength of the division of a network into modules (communities).</p></li><li><p><strong>Layout Algorithms</strong>: Techniques used to position nodes in the visualization space, emphasizing aspects of the network structure (e.g., Force Atlas 2, Fruchterman-Reingold).</p></li><li><p><strong>Force Atlas 2</strong>: A force-directed layout that simulates a physical system to spatially separate all nodes equally, making clusters and dense regions more visible. It is best used for large networks where the general structure needs to be identified.</p></li><li><p><strong>Fruchterman-Reingold</strong>: A force-directed algorithm that aims to minimize the overlap between nodes and distribute them evenly across the network. Ideal for small to medium-sized networks for a balanced visual overview.</p></li><li><p><strong>Yifan Hu</strong>: Combines aspects of force-directed and multiscale algorithms to efficiently layout large networks.</p></li><li><p><strong>Circular Layout</strong>: Positions nodes in a circle, emphasizing the network’s connectivity.</p></li><li><p><strong>Radial Axis</strong>: Arranges nodes around a central node, emphasizing hierarchy or centrality.</p></li><li><p><strong>Random Layout</strong>: Places nodes randomly, serving as a baseline for applying other algorithms.</p></li></ul><h3 id="installing-gephi" tabindex="-1">Installing Gephi <a class="header-anchor" href="#installing-gephi" aria-label="Permalink to &quot;Installing Gephi&quot;">​</a></h3><h3 id="nipr-install" tabindex="-1">NIPR Install <a class="header-anchor" href="#nipr-install" aria-label="Permalink to &quot;NIPR Install&quot;">​</a></h3><ul><li>NOTE: Ask your S6 to install Gephi. NIPR and SIPR access are necessary.</li></ul><h3 id="commercial-system-install" tabindex="-1">Commercial System Install <a class="header-anchor" href="#commercial-system-install" aria-label="Permalink to &quot;Commercial System Install&quot;">​</a></h3><ul><li></li></ul><ol><li><a href="https://gephi.org/users/download/" target="_blank" rel="noreferrer">Download Gephi</a></li></ol><h3 id="gephi-cookbook-and-workflows" tabindex="-1">Gephi Cookbook and Workflows <a class="header-anchor" href="#gephi-cookbook-and-workflows" aria-label="Permalink to &quot;Gephi Cookbook and Workflows&quot;">​</a></h3><h3 id="basic-analysis-workflow" tabindex="-1">Basic Analysis Workflow <a class="header-anchor" href="#basic-analysis-workflow" aria-label="Permalink to &quot;Basic Analysis Workflow&quot;">​</a></h3><ol><li><p><strong>Importing Data</strong>: Start by importing your dataset into Gephi. Use the <code>File &amp;gt; Open</code> option for GEPHI files or <code>File &amp;gt; Import Spreadsheet</code> for GEXF, GDF, DOT, or GML files.</p></li><li><p><strong>Exploring the Graph</strong>: Use the Overview tab to explore your graph’s basic properties. Apply layouts like Force Atlas 2 to uncover the structure of your network.</p></li><li><p><strong>Calculating Metrics</strong>: Analyze your network using Gephi’s built-in metrics under the Statistics window, such as degree distribution and modularity.</p></li><li><p><strong>Visualization</strong>: Adjust node sizes and colors based on metrics. Use the <code>Appearance</code> tab for these visual mappings.</p></li><li><p><strong>Interpretation and Reporting</strong>: Analyze the results to conclude your network, identifying clusters or key influencers.</p></li></ol><h3 id="advanced-techniques" tabindex="-1">Advanced Techniques <a class="header-anchor" href="#advanced-techniques" aria-label="Permalink to &quot;Advanced Techniques&quot;">​</a></h3><ul><li><strong>Dynamic Networks</strong>: For networks that change over time, use GEXF to include time-series data. Gephi supports dynamic visualizations showing network evolution.</li></ul><h3 id="basics" tabindex="-1">Basics <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;Basics&quot;">​</a></h3><ul><li>Gephi Quick Start Guide (here)[* Learn how to use Gephi <a href="https://gephi.org/users/quick-start/%5D" target="_blank" rel="noreferrer">https://gephi.org/users/ here</a></li></ul><h3 id="datasets" tabindex="-1">Datasets <a class="header-anchor" href="#datasets" aria-label="Permalink to &quot;Datasets&quot;">​</a></h3><ul><li><p>Gephi Basic Datasets <a href="https://github.com/gephi/gephi/wiki/Datasets" target="_blank" rel="noreferrer">repo</a></p></li><li><p>Chinese Companies <a href="https://github.com/LOyster1/AutoGephiPipeV3/blob/master/Company-to-Company4.gdf" target="_blank" rel="noreferrer">repo</a></p></li></ul><h3 id="query-for-datasets" tabindex="-1">Query for Datasets <a class="header-anchor" href="#query-for-datasets" aria-label="Permalink to &quot;Query for Datasets&quot;">​</a></h3><p>Basic Advanced Google Query</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;quot;KEYWORD1&amp;quot; OR &amp;quot;KEYWORD2&amp;quot; filetype:GEXF OR filetype:GDF OR filetype:DOT OR filetype:GML OR filetype:GEPHI</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="make-datasets" tabindex="-1">Make Datasets <a class="header-anchor" href="#make-datasets" aria-label="Permalink to &quot;Make Datasets&quot;">​</a></h3><p>Creating your datasets for analysis with Gephi involves a process of data collection, cleaning, and formatting. Here’s a general guide:</p><ol><li><p><strong>Define Your Network</strong>: Decide what the nodes (entities) and edges (relationships) represent.</p></li><li><p><strong>Collect Data</strong>: Gather data relevant to your network.</p></li><li><p><strong>Clean Data</strong>: Ensure consistency in your data by removing duplicates and correcting errors.</p></li><li><p><strong>Format for Gephi</strong>: Convert your data into formats compatible with Gephi (GEXF, GDF, DOT, GML, GEPHI).</p></li><li><p><strong>Create Nodes and Edges Files</strong>: Prepare CSV files for nodes and edges.</p></li><li><p><strong>Import into Gephi</strong>: Import your files via the Data Laboratory tab, then explore your network using Gephi’s tools.</p></li></ol><p>[Tools] [Visualization] [Science]</p>',31)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
